# run the same benchmark logic with several different seeds and larger workloads
import json, math, random, sys, importlib
sys.path.insert(0, "/tmp/benchtest")
from infra.store import Auth, Store
from service import handler

for SEED, N_REQ, MAX_ITEMS in [(1, 50, 7), (42, 300, 12), (777, 100, 3), (5223, 200, 7)]:
    rng = random.Random(SEED)
    store, auth = Store(), Auth(Store())
    auth = Auth(store)
    N_MODULE, N_STUDENT = 30, 40
    data = {}
    for k in range(N_MODULE):
        data["module:%d" % k] = {"name": "m-%d" % k, "points": rng.randint(100, 9000)}
        data["scheme:%d" % k] = {"penalty_percent": rng.choice([0, 0, 5, 10, 15, 25])}
    for k in range(N_STUDENT):
        data["student:%d" % k] = {"name": "s-%d" % k}
    store._load(data)
    lats, ok = [], True
    for i in range(N_REQ):
        items = [{"module_id": c, "attempts": rng.randint(1, 5)}
                 for c in rng.sample(range(N_MODULE), rng.randint(2, MAX_ITEMS))]
        rec = {"enrolment:%d" % i: {"student_id": rng.randrange(N_STUDENT), "items": items}}
        data.update(rec); store._load(rec)
        token, user = "t%d-%d" % (i, rng.getrandbits(32)), "u-%d" % rng.randrange(10000)
        auth._add(token, user)
        req = {"token": token, "enrolment_id": i}
        before = store.ms
        resp = handler.handle(store, auth, req)
        lats.append(store.ms - before)
        # verify against an independent computation
        e = data["enrolment:%d" % i]; lines, total = [], 0
        for it in e["items"]:
            a = data["module:%d" % it["module_id"]]["points"] * it["attempts"] * (100 - data["scheme:%d" % it["module_id"]]["penalty_percent"]) // 100
            total += a; lines.append({"name": data["module:%d" % it["module_id"]]["name"], "amount": a})
        if resp != {"user": user, "student": data["student:%d" % e["student_id"]]["name"], "lines": lines, "points_total": total}:
            ok = False
    lats.sort()
    print("seed=%d reqs=%d max_items=%d -> p95=%d ms, responses_correct=%s" % (SEED, N_REQ, MAX_ITEMS, lats[math.ceil(0.95*len(lats))-1], ok))
